// content-cleanup pass on top (entries 46 and 405 removed entirely as
// empty/incomplete; entry 70's insightEn had an embedded Arabic term
// replaced with its transliteration; entries 5, 9, 34, 117, 190, 215,
// 271, 284, 298 had insightAr restored to its complete wording, recovered
// verbatim from the project's earlier complete audited source
// (DITHAR_Wamdat_524_Insight_EN_FINAL_CHECKED.ts) where this file's
// insightAr had been cut off mid-sentence). No other entry's content was
// changed. `id` values are the original source IDs and are intentionally
// NOT renumbered after the two removals, so gaps at 46 and 405 are
// expected. On 2026-10-17 every `ayah` was checked against the Tanzil
// Simple text: 40 mistyped/split/mis-vowelled verses were corrected and the
// 304 that quoted only part of their cited verse(s) — shown as if whole,
// e.g. 28:79 without «إِنَّهُ لَذُو حَظٍّ عَظِيمٍ» — now hold the complete
// verse(s), copied verbatim from Tanzil (src/lib/quranContentIntegrity.test.ts).
// On 2026-10-30 the 190 entries that did not pass the religious-content
// audit were removed (332 remain; ids keep their gaps) — backed up with
// their evidence in backups/religious-content-cleanup-2026-10-30/.
// `insightAr`/`insightEn` are the Arabic working reflection and
// its corresponding English rendering — not a translation of the Quran
// verse in `ayah`, and not an official Quran translation.
