// `ayah` stores the verse text wrapped in "{...}", with an optional
// trailing ayah marker (AYAH_MARKER_RE below: "[الآية 186]", a range
// "[الآية 62-63]", or "[الآية 124 - آل عمران]"; two entries spanning
// several verses of al-Fatihah omit it in the source). These two helpers
// connect that raw field to the reminder views, which show the verse text
// and a separate reference line. Both read the SAME marker pattern as
// getWamdaQuranRef: an earlier single-number pattern missed ranges and the
// surah-repeated form, so 75 verses were shown with a stray "}" and the raw
// "[الآية …]" marker inside the verse, under a reference with no verse number.

/**
 * Entries whose verse, reference and reflection don't agree, found by
 * checking every verse against the Tanzil text and every word a reflection
 * quotes in «{…}» against the cited verse. Which verse was meant is a
 * content decision, so they are not rewritten: they are held for review
 * (lib/contentReview.ts, "needs-verification") and not shown until approved.
 */
// The three entries once listed here (16, 183, 232) were removed by the
// 2026-10-30 religious-content audit cleanup; the list stays for any new one.
export const WAMDA_NEEDS_VERIFICATION: Readonly<Record<number, string>> = {};

export function getWamdaVerseText(entry: WamdaEntry): string {
  return entry.ayah
    .replace(AYAH_MARKER_RE, "")
    .trim()
    .replace(/^\{/, "")
    .replace(/\}$/, "")
    .trim();
}

export function getWamdaVerseReference(entry: WamdaEntry): string {
  const match = entry.ayah.match(AYAH_MARKER_RE);
  if (!match) return `سورة ${entry.surah}`;
  const [, from, to] = match;
  if (to === undefined || to === from) return `سورة ${entry.surah} – الآية ${from}`;
  const count = Number(to) - Number(from) + 1;
  return `سورة ${entry.surah} – ${count === 2 ? "الآيتان" : "الآيات"} ${from}–${to}`;
}

// Machine-readable Quran reference for Quran audio (see src/lib/quranRef.ts),
// derived ONLY from what each entry itself states: its `surah` name (exact
// match against quranSurahs.ts) plus the trailing marker in `ayah`, which
// the dataset writes in three forms:
//   "[الآية 186]"                — one ayah
//   "[الآية 1-2]"                — an ayah range
//   "[الآية 124 - آل عمران]"      — one ayah, surah repeated (id 183); the
//                                  repeated name must equal `surah`
// Anything else — an unknown surah name, no marker at all (ids 1 and 2,
// both al-Fatihah), a range out of order, or an ayah past the surah's end —
// returns `null` and the entry simply has no Quran audio. Nothing is ever
// inferred from the verse text itself. The display helpers above read the
// same pattern.
const AYAH_MARKER_RE = /\[الآية\s*(\d+)(?:\s*-\s*(\d+))?(?:\s*-\s*([^\]\d][^\]]*?))?\s*\]\s*$/;

export function getWamdaQuranRef(entry: WamdaEntry): QuranRef | null {
  const surah = surahNumberFromArabicName(entry.surah);
  if (surah === undefined) return null;
  const match = entry.ayah.match(AYAH_MARKER_RE);
  if (!match) return null;
  const [, from, to, repeatedSurahName] = match;
  if (repeatedSurahName !== undefined && repeatedSurahName.trim() !== entry.surah) return null;
  const ref: QuranRef = { surah, fromAyah: Number(from), toAyah: Number(to ?? from) };
  return isValidQuranRef(ref) ? ref : null;
}

// English rendering of the Tafsir/source citation — `source` has no
// englishSource field in this dataset. WAMDAT cites from a small, CLOSED
// set of classical works: exactly 17 distinct `source` strings occur
// across all 524 entries (verified against this file), each a well-known
// classical tafsir/scholarly work with one standard, widely-published
// English title (the same class of "translation" as this app's own
// "الكويت" -> "Kuwait" — a proper-noun title, never the Wamda commentary
// text itself, which is never touched here). This dictionary is
// EXHAUSTIVE over that set; getWamdaSourceCitation falls back to `undefined`
// (never invents a rendering) if a future content update ever adds a
// source string outside it.
const WAMDA_SOURCE_EN_MAP: Readonly<Record<string, string>> = {
  "إغاثة اللهفان - ابن القيم.": "Ighathat al-Lahfan by Ibn al-Qayyim",
  "البحر المحيط في التفسير - أبو حيان الأندلسي.": "Al-Bahr al-Muhit fi al-Tafsir by Abu Hayyan al-Andalusi",
  "التحرير والتنوير - ابن عاشور / الإعجاز الطبي.": "Al-Tahrir wa al-Tanwir by Ibn Ashur / Medical Miracles in the Qur'an",
  "التحرير والتنوير - ابن عاشور.": "Al-Tahrir wa al-Tanwir by Ibn Ashur",
  "الخصائص والبلاغة في الكشاف - الزمخشري.": "Al-Khasa'is wa al-Balaghah fi al-Kashshaf by al-Zamakhshari",
  "الفوائد - ابن القيم.": "Al-Fawa'id by Ibn al-Qayyim",
  "الكشاف - الزمخشري.": "Al-Kashshaf by al-Zamakhshari",
  "بدائع الفوائد - الإمام ابن القيم.": "Bada'i al-Fawa'id by Imam Ibn al-Qayyim",
  "تفسير ابن كثير / الإعجاز العلمي في القرآن.": "Tafsir Ibn Kathir / Scientific Miracles in the Qur'an",
  "تفسير ابن كثير / موسوعات الإعجاز الطبي.": "Tafsir Ibn Kathir / Encyclopedias of Medical Miracles",
  "تفسير ابن كثير.": "Tafsir Ibn Kathir",
  "جامع البيان - الطبري.": "Jami' al-Bayan by al-Tabari",
  "زاد المعاد - ابن القيم.": "Zad al-Ma'ad by Ibn al-Qayyim",
  "طريق الهجرتين - ابن القيم.": "Tariq al-Hijratayn by Ibn al-Qayyim",
  "مدارج السالكين - ابن القيم.": "Madarij al-Salikin by Ibn al-Qayyim",
  "مفردات ألفاظ القرآن - الراغب الأصفهاني / تفسير ابن كثير.":
    "Mufradat Alfaz al-Qur'an by al-Raghib al-Isfahani / Tafsir Ibn Kathir",
  "مفردات ألفاظ القرآن - الراغب الأصفهاني.": "Mufradat Alfaz al-Qur'an by al-Raghib al-Isfahani",
};

// Language-appropriate citation for the Quranic Insight card. Arabic
// always returns `entry.source` verbatim. English returns the dictionary
// rendering above when the exact source string is known, or `undefined`
// otherwise (never the Arabic string re-labeled as English) — callers
// should simply omit the citation line when this returns `undefined`.
export function getWamdaSourceCitation(entry: WamdaEntry, language: "ar" | "en"): string | undefined {
  if (language === "ar") return entry.source;
  return WAMDA_SOURCE_EN_MAP[entry.source];
}
